-- R2 customer truth and post-lock authority corrective.

create function e10.assert_customer_writer(p_org uuid,p_cap text,p_message text)
returns void language plpgsql stable security definer set search_path=public as $$
begin
 if auth.uid() is null or not exists(select 1 from public.e10_organizations where id=p_org and status='active')
   or not e10.is_org_member(p_org) or not e10.has_org_cap(p_org,p_cap)
 then raise exception using errcode='42501',message=p_message;end if;
end $$;
revoke all on function e10.assert_customer_writer(uuid,text,text) from public,anon,authenticated;
grant execute on function e10.assert_customer_writer(uuid,text,text) to service_role;

-- Released native sales remain evidence but no longer have an actionable customer.
create or replace function e10.customer_activity_effective_customer(p_org uuid,p_activity uuid)
returns uuid language sql stable security definer set search_path=public as $$
 select case
  when o.source_kind='native' and not exists(
    select 1 from public.e10_current_native_break_sales s
    where s.organization_id=o.organization_id and s.activity_observation_id=o.id)
   then null
  when a.id is not null then case when a.decision_action='attribute' then a.customer_id else null end
  else o.customer_id end
 from public.e10_customer_activity_observations o
 left join public.e10_current_customer_activity_attributions a
  on(a.organization_id,a.activity_observation_id)=(o.organization_id,o.id)
 where o.organization_id=p_org and o.id=p_activity
$$;

-- Validate before any draft line is written so malformed arrays fail atomically
-- with the contract error rather than a storage error.
create function e10.enforce_customer_draft_line_r2() returns trigger
language plpgsql security definer set search_path=public as $$
declare a record;header_currency text;
begin
 if new.quantity is null or new.quantity<=0 or new.quantity::text in('NaN','Infinity','-Infinity')
   or new.merchandise_gross is null or new.merchandise_gross<0 or new.merchandise_gross::text in('NaN','Infinity','-Infinity')
   or(new.merchandise_discount is not null and(new.merchandise_discount<0 or new.merchandise_discount>new.merchandise_gross or new.merchandise_discount::text in('NaN','Infinity','-Infinity')))
   or(new.shipping_amount is not null and(new.shipping_amount<0 or new.shipping_amount::text in('NaN','Infinity','-Infinity')))
   or(new.tax_amount is not null and(new.tax_amount<0 or new.tax_amount::text in('NaN','Infinity','-Infinity')))
 then raise exception using errcode='22023',message='draft_line_amount_invalid';end if;
 if new.activity_observation_id is not null then
  select o.* into a from public.e10_customer_activity_observations o
   where(o.organization_id,o.id)=(new.organization_id,new.activity_observation_id);
  select currency into header_currency from public.e10_customer_transaction_draft_revisions
   where(organization_id,draft_id,revision)=(new.organization_id,new.draft_id,new.revision);
  if a.id is null then raise exception using errcode='42501',message='draft_activity_denied';end if;
  if a.currency<>header_currency then raise exception using errcode='22023',message='draft_activity_currency_mismatch';end if;
  if exists(select 1 from public.e10_customer_transaction_draft_lines l
    where(l.organization_id,l.draft_id,l.revision,l.activity_observation_id)=
      (new.organization_id,new.draft_id,new.revision,new.activity_observation_id))
  then raise exception using errcode='22023',message='draft_activity_duplicate';end if;
  if a.source_kind='native' and not exists(select 1 from public.e10_current_native_break_sales s
    where(s.organization_id,s.activity_observation_id)=(a.organization_id,a.id))
  then raise exception using errcode='42501',message='released_native_sale_not_postable';end if;
 end if;
 if new.capture_source='import' and new.break_slot_id is not null and exists(
   select 1 from public.e10_native_break_sales s
   where(s.organization_id,s.session_id,s.slot_id)=(new.organization_id,new.break_session_id,new.break_slot_id))
 then raise exception using errcode='22023',message='slot_import_requires_reconciliation';end if;
 return new;
end $$;
revoke all on function e10.enforce_customer_draft_line_r2() from public,anon,authenticated;
grant execute on function e10.enforce_customer_draft_line_r2() to service_role;
create trigger e10_customer_draft_line_r2_trg before insert on public.e10_customer_transaction_draft_lines
 for each row execute function e10.enforce_customer_draft_line_r2();

