create function public.e10_org_record_customer_activity(p_org uuid,p_activity_kind text,p_customer_id uuid,p_buyer_user_id uuid,p_buyer_alias text,p_break_session_id uuid,p_break_slot_id uuid,p_quantity numeric,p_merchandise_gross numeric,p_merchandise_discount numeric,p_shipping_amount numeric,p_tax_amount numeric,p_currency text,p_sale_method text,p_occurred_at timestamptz,p_occurred_at_precision text,p_source_kind text,p_source_connection_id text,p_source_reference text,p_source_event_id text,p_raw_payload jsonb,p_evidence_quality text,p_idempotency_key text) returns jsonb language plpgsql security definer set search_path=public as $$begin perform pg_advisory_xact_lock(hashtextextended(p_org::text||'|customer-activity|'||p_idempotency_key,0));perform e10.assert_customer_writer(p_org,'act.record_commercial_events','record_customer_activity_denied');return public._e10_org_record_customer_activity_r2(p_org,p_activity_kind,p_customer_id,p_buyer_user_id,p_buyer_alias,p_break_session_id,p_break_slot_id,p_quantity,p_merchandise_gross,p_merchandise_discount,p_shipping_amount,p_tax_amount,p_currency,p_sale_method,p_occurred_at,p_occurred_at_precision,p_source_kind,p_source_connection_id,p_source_reference,p_source_event_id,p_raw_payload,p_evidence_quality,p_idempotency_key);end$$;
