create function public.e10_org_post_customer_transaction_draft(p_org uuid,p_draft uuid,p_expected_revision integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare a uuid;k text;begin
 perform pg_advisory_xact_lock(hashtextextended(p_org::text||'|customer-commercial|'||p_idempotency_key,0));perform 1 from public.e10_customer_transaction_drafts where organization_id=p_org and id=p_draft for update;
